#!/bin/bash
# land-glass-hub.sh — the finished medical look, in two commits.
#
#   1. "The room finishes what the mock started" — sunrise sky on the work
#      pages, one dense smoked band under each page's content, glass header,
#      glass rail with the city lamp restored.
#   2. "The cards keep the glass" — cards become dark glass wells on the band
#      (the mock's ghost panel), status flags become tinted-glass ghosts,
#      and only true paper (inputs, chips, buttons, modals, stats, rows)
#      keeps the city ink.
#
# This SUPERSEDES land-atmosphere-band.sh — it lands whichever of the two is
# still missing, so it is safe whether or not you ran that one.
#
# WEB ONLY. Push and Vercel takes it.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
case "$LOG" in
  *"The cards turn to glass"*) ;;
  *) echo "!! Needs \"The cards turn to glass\" — run land-glass-cards.sh first."; exit 1 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

apply() { # $1 tmp-prefix, $2 sha, then payload on stdin
  local P; P="$(mktemp "${TMPDIR:-/tmp}/$1.XXXXXX")"
  tr -d '\n' | openssl base64 -d -A > "$P"
  local GOT; GOT="$(shasum -a 256 "$P" | awk '{print $1}')"
  [ "$GOT" = "$2" ] || { echo "!! Patch $1 corrupt (got $GOT)"; rm -f "$P"; exit 1; }
  git apply --check -C1 "$P" || { echo "!! Patch $1 does not apply. Nothing written."; rm -f "$P"; exit 1; }
  git am --keep-cr -C1 < "$P"; rm -f "$P"
}

case "$LOG" in
  *"The room finishes what the mock started"*) echo "== band already landed" ;;
  *) echo "== landing: The room finishes what the mock started"
     apply band 3338e6d2a6c495a26c2c26a40c54545e317ead3156a982268da26fdfbf631e59 <<'B64A'

B64A
     ;;
esac

LOG="$(git log --oneline -40)"
case "$LOG" in
  *"The cards keep the glass"*) echo "== glass cards already landed. Nothing to do."; exit 0 ;;
esac
echo "== landing: The cards keep the glass"
apply glass 4ca23695185f8cab712f7057c2ad51bf76eb40fa99f3e0b496ababf2ee3e4575 <<'B64B'

B64B

cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed. Push and Vercel ships it."
echo " (land-atmosphere-band.sh is superseded by this script — you can"
echo "  delete it along with the other spent land-*.sh files.)"
echo "==============================================================="
